from dataclasses import dataclass, field


@dataclass
class Chunk:
    text: str
    metadata: dict = field(default_factory=dict)


def chunk_document(text, source, title, max_chars=1200, overlap=1, **meta):
    """Split on paragraphs, pack them up to max_chars, repeat the last `overlap` paragraph(s) in the next chunk."""
    paragraphs = [p.strip() for p in text.split("\n\n") if p.strip()]
    groups, current = [], []
    for para in paragraphs:
        if current and len("\n\n".join(current + [para])) > max_chars:
            groups.append(current)
            current = current[-overlap:] if overlap else []
        current.append(para)
    if current:
        groups.append(current)
    return [
        Chunk(
            # the title in front gives context to the embedding ("14 days"... of what?)
            text=f"[{title}]\n" + "\n\n".join(parts),
            metadata={"source": source, "title": title, "chunk": i, **meta},
        )
        for i, parts in enumerate(groups)
    ]


with open("returns_policy.md", encoding="utf-8") as f:
    policy = f.read()

chunks = chunk_document(
    policy, source="returns_policy.md", title="Politique de retour",
    language="fr", updated="2026-09-01", audience="public",
)
for c in chunks:
    print(c.metadata["chunk"], len(c.text), c.text[:60].replace("\n", " "))

