import numpy as np


def cosine(a, b):
    """Cosine similarity of two vectors: 1 = same direction, 0 = unrelated."""
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    return float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b)))

def mrr(runs):
    """runs: list of (ranked_ids, relevant_ids). Mean of 1/rank of the first relevant hit (0 if none)."""
    total = 0.0
    for ranked_ids, relevant_ids in runs:
        for rank, chunk_id in enumerate(ranked_ids, start=1):
            if chunk_id in relevant_ids:
                total += 1.0 / rank
                break
    return total / len(runs) if runs else 0.0

def check_quotes(quotes, passages):
    """quotes: list of (source, quoted_text); passages: list of dicts with 'source' and 'content'.
    Return the quotes that do NOT appear word for word in their source passage."""
    by_source = {p["source"]: " ".join(p["content"].split()) for p in passages}
    missing = []
    for source, quoted in quotes:
        text = by_source.get(source, "")
        if " ".join(quoted.split()) not in text:
            missing.append((source, quoted))
    return missing
